def shift_chars(text: str, n: int) -> str:
    out = []
    for ch in text:
        if "a" <= ch <= "z":
            out.append(chr((ord(ch) - 97 + n) % 26 + 97))
        elif "A" <= ch <= "Z":
            out.append(chr((ord(ch) - 65 + n) % 26 + 65))
        else:
            out.append(ch)
    return "".join(out)

def is_palindrome(text: str) -> bool:
    cleaned = "".join(ch.lower() for ch in text if ch.isalnum())
    return cleaned == cleaned[::-1]

def unique_keep(items):
    seen = []
    for item in items:
        if item not in seen:
            seen.append(item)
    return seen

def flatten_once(rows):
    out = []
    for row in rows:
        out.extend(row)
    return out

def group_lengths(words):
    grouped = {}
    for word in words:
        grouped.setdefault(len(word), []).append(word)
    return grouped

