def parse_positive_ints(text: str):
    if not text.strip():
        raise ValueError(text)
    values = []
    for part in text.split(","):
        token = part.strip()
        if not token or not token.isdigit() or int(token) <= 0:
            raise ValueError(text)
        values.append(int(token))
    return values

