def first_int(text: str) -> int:
    digits = []
    started = False
    for ch in text:
        if ch.isdigit():
            digits.append(ch)
            started = True
        elif started:
            break
    if not digits:
        raise ValueError(text)
    return int("".join(digits))

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def binary_search(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def balanced(text: str) -> bool:
    depth = 0
    for ch in text:
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0

def max_sum(nums):
    best = nums[0]
    running = nums[0]
    for value in nums[1:]:
        running = value if running < 0 else running + value
        if running > best:
            best = running
    return best

def fib(n: int) -> int:
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a
